<!doctype html>
<html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;color:#172033;font-size:9px}h1{font-size:17px;margin:0 0 4px}p{color:#475569;margin:0 0 12px}table{border-collapse:collapse;width:100%}th,td{border:1px solid #94a3b8;padding:6px;vertical-align:top}th{background:#173b63;color:#fff;text-align:left}.holiday{background:#f3e8ff}.present{background:#dcfce7}.absent{background:#fee2e2}</style></head><body><h1>BAIUST — My Attendance Report</h1><p><strong>{{ $person->PersonName }}</strong> · {{ $person->RoleName }}@if($person->SelectedDepartment) · {{ $person->SelectedDepartment }}@endif<br>Period: {{ \Carbon\Carbon::parse($fromDate)->format('d M Y') }} to {{ \Carbon\Carbon::parse($toDate)->format('d M Y') }}</p><p>Scheduled duties: {{ $summary['Scheduled'] }} · Present: {{ $summary['Present'] }} · Absent: {{ $summary['Absent'] }} · Actual work: {{ number_format((float) $summary['ActualMinutes'], 0) }} min</p><table><thead><tr><th>Date</th><th>Duty / Subject</th><th>Location</th><th>Scheduled time</th><th>Check-in / out</th><th>Status</th></tr></thead><tbody>@forelse($rows as $row)<tr class="{{ $row['Status'] === 'Holiday' ? 'holiday' : ($row['Status'] === 'Present' ? 'present' : ($row['Status'] === 'Absent' ? 'absent' : '')) }}"><td>{{ \Carbon\Carbon::parse($row['RosterDate'])->format('d M Y') }}</td><td>{{ $row['AssignmentType'] }}@if($row['SubjectName'])<br>{{ $row['SubjectCode'] }} — {{ $row['SubjectName'] }}@endif@if($row['HolidayName'])<br>{{ $row['HolidayName'] }}@endif</td><td>{{ $row['LocationName'] ?? '-' }}</td><td>{{ $row['Start'] }} – {{ $row['End'] }}</td><td>{{ $row['CheckIn'] ?? '-' }} – {{ $row['CheckOut'] ?? '-' }}</td><td><strong>{{ $row['Status'] }}</strong></td></tr>@empty<tr><td colspan="6">No attendance records found for this period.</td></tr>@endforelse</tbody></table><p style="margin-top:14px">Generated: {{ now()->format('d M Y h:i A') }}</p></body></html>
